/* One Design System, Three Products, Any Brand — prototype: the page wears a brand; evidence, rendered from one set of tokens.
   The invented brand's scales follow the real system's rules (fixed lightness per step); the lightness chart uses
   the real system's lightness values, which carry no brand. */
(() => {
  "use strict";

  /* ---------- tokens (invented brand; generated by gen.py, every text pairing ≥ 4.5:1) ---------- */
  const SCALES = {"light": {"brand": {"50": "#f1f5ff", "200": "#abc3ff", "500": "#5b81ff", "600": "#3453d3", "700": "#2c45ae"}, "blue": {"50": "#eff6ff", "200": "#9cc7ff", "500": "#1f8aff", "600": "#0061be", "700": "#0051a0"}, "green": {"50": "#e8fbea", "200": "#92d89c", "500": "#00a943", "600": "#00782d", "700": "#006425"}, "red": {"50": "#fff2f0", "200": "#ffaba3", "500": "#ed4a49", "600": "#bb061e", "700": "#9b0f1b"}, "purple": {"50": "#f9f2ff", "200": "#dab0fa", "500": "#b161e5", "600": "#8632b6", "700": "#6f2c96"}, "amber": {"50": "#fff3e4", "200": "#ffce8a", "500": "#eba000", "600": "#956300", "700": "#7e5400"}}, "dark": {"brand": {"50": "#0c142d", "200": "#233056", "500": "#5379fd", "600": "#90aeff", "700": "#b4c9ff"}, "blue": {"50": "#05162c", "200": "#183356", "500": "#0c84fa", "600": "#79b4ff", "700": "#a7ceff"}, "green": {"50": "#031c08", "200": "#153c1d", "500": "#00a240", "600": "#6dc97d", "700": "#a3dbaa"}, "red": {"50": "#290b0a", "200": "#512320", "500": "#e64343", "600": "#fe8b83", "700": "#ffb5ae"}, "purple": {"50": "#1d0f27", "200": "#3e284d", "500": "#ab5ade", "600": "#cc97f3", "700": "#ddbbf7"}, "amber": {"50": "#211300", "200": "#472d00", "500": "#c38400", "600": "#e7af5c", "700": "#f4c98e"}}};
  const NEUTRAL = {"light": {"background": "#ffffff", "card": "#ffffff", "foreground": "#09090b", "muted": "#f4f4f5", "muted-foreground": "#71717b", "border": "#e4e4e7", "input": "#f4f4f5"}, "dark": {"background": "#09090b", "card": "#18181b", "foreground": "#fafafa", "muted": "#27272a", "muted-foreground": "#9f9fa9", "border": "#2d2d31", "input": "#1f1f23"}};
  const HUES = [["brand", "Brand", "primary"], ["blue", "Blue", "info"], ["green", "Green", "success"], ["red", "Red", "destructive"], ["purple", "Purple", "categorical"], ["amber", "Amber", "warning"]];
  const STEPS = [["50", "Surface"], ["200", "Border"], ["500", "Charts, icons"], ["600", "Text on white"], ["700", "Text on a tint"]];
  /* the real system's lightness per step (light mode); hue-free, so safe to show */
  const REAL_L = {
    "50": { brand: .97, blue: .97, green: .97, red: .97, purple: .97, amber: .97 },
    "200": { brand: .82, blue: .82, green: .82, red: .82, purple: .82, amber: .88 },
    "500": { blue: .623, green: .64, red: .65, purple: .63, amber: .76 },
    "600": { brand: .50, blue: .50, green: .50, red: .52, purple: .50, amber: .54 },
    "700": { brand: .44, blue: .44, green: .44, red: .45, purple: .44, amber: .48 },
  };

  /* ---------- colour maths: OKLab/OKLCH ↔ sRGB, WCAG 2 contrast ---------- */
  const toLin = (v) => (v <= 0.04045 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4);
  const toGam = (v) => (v <= 0.0031308 ? 12.92 * v : 1.055 * v ** (1 / 2.4) - 0.055);
  function hexToRgb(h) { h = h.replace("#", ""); if (h.length === 3) h = [...h].map((x) => x + x).join(""); return [0, 2, 4].map((i) => parseInt(h.slice(i, i + 2), 16) / 255); }
  function rgbToHex(rgb) { return "#" + rgb.map((v) => Math.round(Math.min(1, Math.max(0, v)) * 255).toString(16).padStart(2, "0")).join(""); }
  function rgbToOklab([r, g, b]) {
    [r, g, b] = [r, g, b].map(toLin);
    const l = Math.cbrt(0.4122214708 * r + 0.5363325363 * g + 0.0514459929 * b);
    const m = Math.cbrt(0.2119034982 * r + 0.6806995451 * g + 0.1073969566 * b);
    const s = Math.cbrt(0.0883024619 * r + 0.2817188376 * g + 0.6299787005 * b);
    return [0.2104542553 * l + 0.793617785 * m - 0.0040720468 * s, 1.9779984951 * l - 2.428592205 * m + 0.4505937099 * s, 0.0259040371 * l + 0.7827717662 * m - 0.808675766 * s];
  }
  function oklabToLin([L, a, b]) {
    const l = (L + 0.3963377774 * a + 0.2158037573 * b) ** 3, m = (L - 0.1055613458 * a - 0.0638541728 * b) ** 3, s = (L - 0.0894841775 * a - 1.291485548 * b) ** 3;
    return [4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s, -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s, -0.0041960863 * l - 0.7034186147 * m + 1.707614701 * s];
  }
  const lch = (lab) => ({ l: lab[0], c: Math.hypot(lab[1], lab[2]), h: ((Math.atan2(lab[2], lab[1]) * 180) / Math.PI + 360) % 360 });
  const lab = ({ l, c, h }) => [l, c * Math.cos((h * Math.PI) / 180), c * Math.sin((h * Math.PI) / 180)];
  const inside = (v) => v.every((x) => x >= -1e-4 && x <= 1 + 1e-4);
  function inGamut(c) { if (inside(oklabToLin(lab(c)))) return c; let lo = 0, hi = c.c; for (let i = 0; i < 20; i++) { const mid = (lo + hi) / 2; if (inside(oklabToLin(lab({ ...c, c: mid })))) lo = mid; else hi = mid; } return { ...c, c: lo }; }
  const hexToLch = (h) => lch(rgbToOklab(hexToRgb(h)));
  const lchToHex = (c) => rgbToHex(oklabToLin(lab(inGamut(c))).map(toGam));
  function lum(h) { const [r, g, b] = hexToRgb(h).map(toLin); return 0.2126 * r + 0.7152 * g + 0.0722 * b; }
  function ratio(a, b) { const [x, y] = [lum(a), lum(b)].sort((p, q) => q - p); return (x + 0.05) / (y + 0.05); }
  function mix(a, b, t) { const A = rgbToOklab(hexToRgb(a)), B = rgbToOklab(hexToRgb(b)); return rgbToHex(oklabToLin(A.map((v, i) => v * t + B[i] * (1 - t))).map(toGam)); }

  /* ---------- the rule: the customer chooses the hue, the system chooses the lightness ---------- */
  const AA = 4.6; // a little over 4.5, so values still pass after rounding
  const NEAR_WHITE = "#fafafa", NEAR_BLACK = "#09090b";
  function readableOn(brand, surfaces, dir) {
    const ok = (l) => surfaces.every((s) => ratio(lchToHex({ ...brand, l }), s) >= AA);
    if (ok(brand.l)) return lchToHex(brand);
    let good = dir === "darker" ? 0 : 1, bad = brand.l;
    for (let i = 0; i < 24; i++) { const mid = (good + bad) / 2; if (ok(mid)) good = mid; else bad = mid; }
    return lchToHex({ ...brand, l: good });
  }
  const pickOn = (fill) => (ratio(NEAR_WHITE, fill) >= AA || ratio(NEAR_WHITE, fill) >= ratio(NEAR_BLACK, fill) ? NEAR_WHITE : NEAR_BLACK);

  /** All the tokens a panel needs, for one colour, one mode and one rule. */
  function theme(hex, mode, rule = "derived") {
    const n = NEUTRAL[mode], s = SCALES[mode], dark = mode === "dark";
    const b = hexToLch(hex);
    const t = {
      "--bg": n.background, "--card": n.card, "--fg": n.foreground, "--muted": n.muted, "--muted-fg": n["muted-foreground"],
      "--border": n.border, "--input": n.border, "--input-bg": n.input,
      "--primary": hex,
    };
    if (rule === "derived") {
      const cont = lchToHex({ l: dark ? 0.2 : 0.97, c: Math.min(b.c, dark ? 0.05 : 0.03), h: b.h });
      Object.assign(t, {
        "--primary-fg": pickOn(hex),
        "--primary-text": readableOn(b, dark ? [n.background, n.card] : [n.background, n.card], dark ? "lighter" : "darker"),
        "--primary-container": cont,
        "--primary-container-fg": readableOn(b, [cont], dark ? "lighter" : "darker"),
        "--primary-border": lchToHex({ l: dark ? 0.32 : 0.82, c: Math.min(b.c, dark ? 0.07 : 0.11), h: b.h }),
      });
    } else {
      /* the first version: the colour written straight into the primary tokens */
      Object.assign(t, {
        "--primary-fg": NEAR_WHITE,
        "--primary-text": hex,
        "--primary-container": mix(hex, n.background, 0.18),
        "--primary-container-fg": hex,
        "--primary-border": mix(hex, n.border, 0.35),
      });
    }
    t["--ring"] = t["--primary-text"];
    const roles = { success: "green", warning: "amber", destructive: "red", info: "blue", categorical: "purple" };
    for (const [role, hue] of Object.entries(roles)) {
      t[`--${role}`] = s[hue]["500"];
      t[`--${role}-container`] = s[hue]["50"];
      t[`--${role}-container-fg`] = s[hue]["700"];
      t[`--${role}-border`] = s[hue]["200"];
      t[`--${role}-text`] = s[hue]["600"];
    }
    t["--destructive"] = dark ? s.red["600"] : s.red["600"];
    return t;
  }
  const apply = (el, t) => { for (const [k, v] of Object.entries(t)) el.style.setProperty(k, v); };
  const chip = (r) => { const ok = r >= 4.5; return `<span class="ds-ratio ${ok ? "is-pass" : "is-fail"}" title="Text contrast ${r.toFixed(2)}:1, ${ok ? "passes" : "fails"} AA"><i>Aa</i>${r.toFixed(2)}:1<b aria-label="${ok ? "passes" : "fails"}">${ok ? "✓" : "✕"}</b></span>`; };
  const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c]);

  const ICON_WARN = '<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M8 2.5 14 13H2z" stroke-linejoin="round"/><path d="M8 6.5v3M8 11.3v.2" stroke-linecap="round"/></svg>';

  function appHTML(c) {
    return `
      <div class="tp-head">
        <span class="tp-logo" aria-hidden="true">${c.mark}</span><b>Deliveries</b>
        <nav class="tp-tabs" aria-label="Example navigation"><span class="is-on">Today<span data-r="tab"></span></span><span>Routes</span><span>Drivers</span><span>Reports</span></nav>
        <span class="tp-user" aria-hidden="true"></span>
      </div>
      <div class="tp-body">
        <section class="tp-card" aria-label="Today's runs">
          <div class="tp-actions"><h4>Today's runs</h4><div><span class="ui-btn is-outline">Export</span><span class="ui-btn is-primary">New run<span data-r="btn"></span></span></div></div>
          <div class="tp-filters">
            <div class="ui-field"><span class="ui-input is-placeholder">Search runs</span></div>
            <div class="ui-field"><span class="ui-select is-static">All depots</span></div>
          </div>
          <ul class="tp-rows">
            <li><b>Run 4821</b><span class="ui-badge r-success">Delivered<span data-r="ok"></span></span><small>14 stops · North depot</small></li>
            <li><b>Run 4822</b><span class="ui-badge r-warning">Delayed</span><small>9 stops · Harbour depot</small></li>
            <li><b>Run 4823</b><span class="ui-badge r-info">On the road</span><small>11 stops · North depot</small></li>
            <li><b>Run 4824</b><span class="ui-badge r-destructive">Failed</span><small>3 stops · Harbour depot</small></li>
          </ul>
          <div class="tp-actions"><div class="ui-pages" aria-label="Pages"><span class="is-on">1</span><span>2</span><span>3</span><span>…</span><span>10</span></div></div>
        </section>
        <section class="tp-card" aria-label="Driver">
          <h4>Run 4822</h4>
          <p>Two stops are behind schedule.<span data-r="muted"></span></p>
          <div class="ui-alert r-warning" role="note">${ICON_WARN}<span><strong>Delayed</strong> by 25 minutes at Harbour depot.</span></div>
          <div class="ui-field"><span>Note for the driver <b>*</b></span><small>Shown on their phone at the next stop.</small><span class="ui-input is-error is-placeholder">Write a note</span><small class="ui-err">A note is required.</small></div>
          <div class="tp-actions"><div><span class="ui-btn is-ghost">Cancel</span><span class="ui-btn is-primary">Send</span></div></div>
        </section>
      </div>`;
  }

  function fillRatios(root, t) {
    const set = (k, r) => { const el = root.querySelector(`[data-r="${k}"]`); if (el) el.innerHTML = chip(r); };
    set("btn", ratio(t["--primary-fg"], t["--primary"]));
    set("link", ratio(t["--primary-text"], t["--card"]));
    set("tab", ratio(t["--primary-container-fg"], t["--primary-container"]));
    set("ok", ratio(t["--success-container-fg"], t["--success-container"]));
    set("muted", ratio(t["--muted-fg"], t["--card"]));
  }

  /* ---------- the page wears a brand: one colour in, the case file's palette out ---------- */
  const INK = "#1c1b19", PAPER = "#fbfaf7", PAPER_D = "#1f1e1c", INSET_D = "#282624";
  const pickPage = (f) => (ratio(NEAR_WHITE, f) >= AA ? NEAR_WHITE : INK);
  const tone = (b, l, c) => lchToHex({ l, c: Math.min(b.c, c), h: b.h });
  function secondOn(on, field) { for (const t of [0.74, 0.8, 0.86, 0.92]) { const m = mix(on, field, t); if (ratio(m, field) >= AA) return m; } return on; }
  function pagePalette(hex) {
    const b = hexToLch(hex);
    const L = {}, D = {};
    // light page
    L.field = hex; L["on-field"] = pickPage(hex); L["on-field-2"] = secondOn(L["on-field"], hex);
    const pale = L["on-field"] === INK;
    L.accent = pale ? INK : readableOn(b, [PAPER, "#ffffff"], "darker");
    L["accent-strong"] = L.accent; L["on-accent"] = pale ? hex : pickOn(L.accent);
    L["ds-mark"] = hex; L["ds-mark-ink"] = pickPage(hex);
    L["accent-2"] = tone(b, 0.94, 0.05); L["accent-tint"] = tone(b, 0.975, 0.03);
    const dk = tone(b, 0.19, 0.016);
    Object.assign(L, { dark: dk, "on-dark": "#f5f3ee", "on-dark-body": "#d4d0c7", "on-dark-2": "#a29e95", "dark-rule": tone(b, 0.27, 0.016), "dark-line": tone(b, 0.42, 0.02), "dark-inset": tone(b, 0.23, 0.016) });
    L["accent-on-dark"] = ratio(hex, dk) >= AA ? hex : readableOn(b, [dk], "lighter");
    // dark page: fields deeper or lifted just enough to sit on the dark studio; text by the same rule
    const fd = b.l > 0.8 ? lchToHex({ ...b, l: 0.8 }) : b.l < 0.36 ? lchToHex({ ...b, l: 0.4 }) : hex;
    D.field = fd; D["on-field"] = pickPage(fd); D["on-field-2"] = secondOn(D["on-field"], fd);
    D.accent = ratio(hex, PAPER_D) >= AA && ratio(hex, INSET_D) >= AA ? hex : readableOn(b, [PAPER_D, INSET_D], "lighter");
    D["accent-strong"] = D.accent; D["on-accent"] = pickOn(D.accent);
    D["ds-mark"] = D.accent; D["ds-mark-ink"] = pickPage(D.accent);
    D["accent-2"] = tone(b, 0.27, 0.04); D["accent-tint"] = tone(b, 0.25, 0.035);
    const dd = tone(b, 0.15, 0.014);
    Object.assign(D, { dark: dd, "dark-rule": tone(b, 0.23, 0.025), "dark-line": tone(b, 0.38, 0.03), "dark-inset": tone(b, 0.2, 0.025) });
    D["accent-on-dark"] = ratio(hex, dd) >= AA ? hex : readableOn(b, [dd], "lighter");
    return { L, D };
  }
  const vars = (o) => Object.entries(o).map(([k, v]) => `--${k}:${v}`).join(";");
  const sheet = document.getElementById("ds-palette");

  /* ---------- customers (invented) ---------- */
  const CUSTOMERS = [
    { id: "courier", name: "Courier", colour: "#f2c94c", font: '"Archivo", var(--sans)', weight: 700, track: "-0.035em", r: "0", btn: "0", mark: "C" },
    { id: "platform", name: "Platform", colour: "#3453d3", font: '"Geist", var(--sans)', weight: 600, track: "-0.045em", r: "0.5rem", btn: "0.5rem", mark: "P" },
    { id: "grocer", name: "Grocer", colour: "#2e7d3a", font: '"Fraunces", Georgia, serif', weight: 600, track: "-0.025em", r: "0.75rem", btn: "999px", mark: "G" },
    { id: "bank", name: "Bank", colour: "#1d2b5c", font: '"IBM Plex Sans", var(--sans)', weight: 600, track: "-0.035em", r: "0.375rem", btn: "0.75rem", mark: "B" },
  ];
  const state = { id: "courier", own: "#e85d9a", mode: "light", ratios: false };
  const current = () => (state.id === "own" ? { ...CUSTOMERS[1], id: "own", name: "Your own", colour: state.own, mark: "Y" } : CUSTOMERS.find((c) => c.id === state.id));
  const listeners = [];
  function setCustomer(id) {
    state.id = id;
    const c = current();
    const { L, D } = pagePalette(c.colour);
    const stack = c.font.replace("var(--sans)", '"Geist", ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif');
    const extra = `--sans:${stack};--ds-btn-font:${stack};--ds-btn-r:${c.btn};--ds-title-font:${stack};--ds-title-weight:${c.weight};--ds-title-track:${c.track}`;
    sheet.textContent = `[data-palette="design-system"]{${vars(L)};${extra}}
@media (prefers-color-scheme: dark){:root:not([data-theme="light"]) [data-palette="design-system"]{${vars(D)}}}
:root[data-theme="dark"] [data-palette="design-system"]{${vars(D)}}`;
    document.querySelectorAll(`input[data-cust]`).forEach((i) => (i.checked = i.value === id));
    listeners.forEach((fn) => fn(c));
  }

  /* ---------- cover: "Seen as" and the layers ---------- */
  const seen = document.getElementById("seen-as");
  if (seen) {
    seen.innerHTML = `<span>Seen as</span>` + CUSTOMERS.map((c) => `<label style="font-family:${c.font.replace(/"/g, "&quot;")};font-weight:${c.weight === 700 ? 600 : 500}"><input type="radio" name="seen" data-cust value="${c.id}" id="seen-${c.id}"><i class="ds-dot" style="background:${c.colour}"></i>${c.name}</label>`).join("");
    // the last option: any colour of your own. The radio keeps it in the keyboard's arrow order; the colour well over the
    // chip opens the picker on click, and choosing a colour runs the same rule as the four brands.
    seen.innerHTML += `<i class="ds-or" aria-hidden="true"></i><label class="ds-seen-own" style="--own:${state.own}">
      <input type="radio" name="seen" data-cust value="own" id="seen-own" aria-label="Or your own colour">
      <i class="ds-rainbow" aria-hidden="true"></i><span class="ds-own-t">Or your own</span><span class="ds-own-hex"></span>
      <input type="color" id="seen-own-colour" value="${state.own}" aria-label="Pick your own brand colour"></label>`;
    const ownChip = seen.querySelector(".ds-seen-own"), ownHex = seen.querySelector(".ds-own-hex");
    const ownWell = seen.querySelector("#seen-own-colour");
    const showOwn = () => { ownChip.style.setProperty("--own", state.own); ownHex.textContent = state.own.toUpperCase(); };
    showOwn();
    ownWell.addEventListener("click", () => { if (state.id !== "own") setCustomer("own"); });
    ownWell.addEventListener("input", (e) => { state.own = e.target.value; showOwn(); setCustomer("own"); });
    seen.addEventListener("change", (e) => { if (e.target.name === "seen") setCustomer(e.target.value); });
  }
  const layersArt = document.getElementById("cover-layers");
  if (layersArt) {
    // the overview's build, small: the foundation strip, three products, two clients above each; the current brand is the solid one
    const OX = 80, OY = 118;
    const P = (x, y, z) => [OX + (x - y) * 0.433, OY + (x + y) * 0.25 - z * 0.5];
    const pts = (a) => a.map(([x, y]) => `${x.toFixed(1)},${y.toFixed(1)}`).join(" ");
    const quad = (cx, cy, hx, hy, z) => [P(cx - hx, cy - hy, z), P(cx + hx, cy - hy, z), P(cx + hx, cy + hy, z), P(cx - hx, cy + hy, z)];
    const PC = [[15, 105], [225, 135], [375, 75]], H = 45; // as in the overview: 3 × 3 studs, one stud past the base
    const slots = [[0, 1], [0, -1], [1, 1], [1, -1], [2, 1], [2, -1]]; // back brick first
    const which = { courier: "0,1", grocer: "0,-1", bank: "1,1" };
    const draw = (c) => {
      const mine = which[c.id];
      let g = `<svg viewBox="-6 -10 304 270" role="img" aria-label="One shared package, three products above it, clients above each product">`;
      g += `<polygon class="cl-base" points="${pts(quad(195, 75, 195, 75, 0))}"/>`;
      [0, 1, 2].sort((a, b) => PC[a][0] + PC[a][1] - (PC[b][0] + PC[b][1])).forEach((p) => {
        const [x, y] = PC[p];
        const a1 = P(x, y, 0), a2 = P(x, y, 108);
        g += `<line class="cl-pin" x1="${a1[0]}" y1="${a1[1]}" x2="${a2[0]}" y2="${a2[1]}"/><polygon class="cl-prod${!mine && p === 0 ? " is-on" : ""}" points="${pts(quad(x, y, H, H, 108))}"/>`;
        slots.filter(([q]) => q === p).forEach(([, side]) => {
          const cx = x - side * 30, cy = y, on = mine === `${p},${side}`;
          const b1 = P(cx, cy, 108), b2 = P(cx, cy, 196);
          g += `<line class="cl-pin${on ? " is-on" : ""}" x1="${b1[0]}" y1="${b1[1]}" x2="${b2[0]}" y2="${b2[1]}"/><polygon class="cl-cli${on ? " is-on" : ""}" points="${pts(quad(cx, cy, 15, 45, 196))}"/>`;
        });
      });
      g += `</svg>`;
      layersArt.innerHTML = g;
    };
    listeners.push(draw);
  }

  /* ---------- the work: the theme panel follows "Seen as" ---------- */
  const work = document.getElementById("work-panel");
  if (work) {
    work.innerHTML = `
      <div class="tp-controls">
        <div class="tp-left">
          <div class="ds-seg" role="radiogroup" aria-label="Customer">
            ${CUSTOMERS.map((c) => `<label><input type="radio" name="tp-customer" data-cust value="${c.id}" id="tp-c-${c.id}"><i class="ds-dot" style="background:${c.colour}"></i>${esc(c.name)}</label>`).join("")}
          </div>
        </div>
        <div class="tp-right">
          <div class="ds-seg" role="radiogroup" aria-label="Mode">
            <label><input type="radio" name="tp-mode" id="tp-m-light" value="light" checked>Light</label>
            <label><input type="radio" name="tp-mode" id="tp-m-dark" value="dark">Dark</label>
          </div>
          <label class="ds-check"><input type="checkbox" id="tp-ratios"> Show text contrast</label>
        </div>
      </div>
      <div class="tp-app ui" id="tp-app"></div>`;
    const app = work.querySelector("#tp-app");
    const render = (c) => {
      app.innerHTML = appHTML(c);
      const t = theme(c.colour, state.mode);
      apply(app, t);
      app.style.setProperty("--font", c.font); app.style.setProperty("--r", c.r); app.style.setProperty("--btn-r", c.btn);
      app.style.colorScheme = state.mode;
      fillRatios(app, t);
      app.classList.toggle("show-ratios", state.ratios);
    };
    listeners.push(render);
    work.addEventListener("change", (e) => {
      if (e.target.name === "tp-customer") return setCustomer(e.target.value);
      if (e.target.name === "tp-mode") state.mode = e.target.value;
      if (e.target.id === "tp-ratios") state.ratios = e.target.checked;
      render(current());
    });
  }

  /* ---------- 01.1: the same screen, three products ---------- */
  document.querySelectorAll("[data-mp]").forEach((el) => {
    el.innerHTML = `<div class="mp-bar"><i class="mp-logo"></i><b>Deliveries</b><span>Today</span></div>
      <div class="mp-main"><div class="mp-top"><h4>Today's runs</h4><span class="mp-btn">New run</span></div>
      <ul class="mp-list"><li><span>Run 4821</span><span class="mp-badge">On time</span></li><li><span>Run 4822</span><span class="mp-badge is-warn">Delayed</span></li><li><span>Run 4823</span><span class="mp-badge">On time</span></li><li><span>Run 4824</span><span class="mp-badge">On time</span></li></ul></div>`;
  });

  /* ---------- 01.2: the same library in code. Figma shows the file; Code shows the source (tokens, two components)
     beside what it renders, light and dark. Choosing a file lights up the parts it draws. ---------- */
  const codeSide = document.getElementById("code-side");
  if (codeSide) {
    const FILES = {
      "tokens.css": { part: "all", src: `/* shared package: every product imports this */
:root {
  --brand-50:  oklch(0.97 0.014 268);
  --brand-200: oklch(0.82 0.089 268);
  --brand-600: oklch(0.5 0.2 268);
  --brand-700: oklch(0.44 0.17 268);

  /* roles: components ask for these, never a hue */
  --primary: var(--brand-600);
  --primary-foreground: oklch(0.985 0 0);
  --ring: var(--brand-200);
  --success-text: var(--green-600);
  --warning-text: var(--amber-700);
}

.dark {
  /* text steps re-tuned, not inverted */
  --brand-600: oklch(0.76 0.122 268);
  --primary: oklch(0.5 0.2 268);
}` },
      "button.tsx": { part: "btn", src: `import { cva } from "class-variance-authority"

export const buttonVariants = cva(
  ["inline-flex items-center rounded-md",
   "text-sm font-medium",
   "focus-visible:ring-[3px] ring-ring"],
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground",
        outline: "border bg-background",
        ghost: "hover:bg-accent",
        destructive: "bg-destructive text-white",
      },
    },
    defaultVariants: { variant: "default" },
  },
)` },
      "badge.tsx": { part: "badge", src: `import { cva } from "class-variance-authority"

// a badge takes a role; the role picks the colours
export const badgeVariants = cva(
  "rounded-full border px-2 text-xs font-medium",
  {
    variants: {
      role: {
        success: "bg-success-container text-success-text",
        warning: "bg-warning-container text-warning-text",
        danger:  "bg-danger-container text-danger-text",
        info:    "bg-info-container text-info-text",
        primary: "bg-primary-container text-primary-text",
      },
    },
  },
)

<Badge role="success">Delivered</Badge>` },
    };
    const RX_CODE = /(\/\*[\s\S]*?\*\/|\/\/[^\n]*)|("[^"\n]*")|(oklch\([^)]*\))|(--[\w-]+)|\b(import|from|export|const)\b|(<\/?[A-Z][\w.]*|\/?>)|(\b[\w-]+(?=:\s))/g;
    const hl = (src) => {
      let out = "", last = 0, m;
      RX_CODE.lastIndex = 0;
      while ((m = RX_CODE.exec(src))) {
        out += esc(src.slice(last, m.index));
        const [t] = m;
        if (m[1]) out += `<span class="c">${esc(t)}</span>`;
        else if (m[2]) out += `<span class="s">${esc(t)}</span>`;
        else if (m[3]) out += `<i class="sw" style="background:${t}"></i><span class="n">${esc(t)}</span>`;
        else if (m[4]) out += `<span class="v">${esc(t)}</span>`;
        else if (m[5]) out += `<span class="k">${esc(t)}</span>`;
        else if (m[6]) out += `<span class="t">${esc(t)}</span>`;
        else out += `<span class="p">${esc(t)}</span>`;
        last = m.index + t.length;
      }
      out += esc(src.slice(last));
      return out.split("\n").map((l) => `<span class="ln">${l || " "}</span>`).join("");
    };
    const pane = (mode) => `<div class="ds-f2c-pane ui" data-mode="${mode}">
        <span class="ds-f2c-mode">${mode === "light" ? "Light" : "Dark"}</span>
        <div class="ds-f2c-row" data-part="btn"><span class="ui-btn is-primary">Settings</span><span class="ui-btn is-outline">Settings</span><span class="ui-btn is-ghost">Settings</span><span class="ui-btn is-destructive">Settings</span></div>
        <div class="ds-f2c-row" data-part="btn"><span class="ui-input is-focus">Placeholder text</span></div>
        <div class="ds-f2c-row" data-part="badge"><span class="ui-badge r-success">Delivered</span><span class="ui-badge r-warning">Delayed</span><span class="ui-badge r-destructive">Failed</span><span class="ui-badge r-info">On the road</span><span class="ui-badge r-primary">Today</span></div>
      </div>`;
    const names = Object.keys(FILES);
    codeSide.innerHTML = `<div class="ds-f2c-editor">
        <div class="ds-f2c-tabs" role="tablist" aria-label="Source files">${names.map((n, i) => `<button type="button" role="tab" id="f2c-tab-${i}" aria-selected="${i === 0}" aria-controls="f2c-src" data-file="${n}">${n}</button>`).join("")}</div>
        <pre class="ds-f2c-src" id="f2c-src" role="tabpanel" tabindex="0"><code></code></pre>
      </div>
      <div class="ds-f2c-out" aria-label="What this code renders"><span class="ds-f2c-cap">Rendered from this code</span>${pane("light")}${pane("dark")}</div>`;
    const brand = SCALES.light.brand["600"];
    codeSide.querySelectorAll(".ds-f2c-pane").forEach((p) => {
      const t = theme(brand, p.dataset.mode);
      if (p.dataset.mode === "dark") { t["--primary-fg"] = "#fafafa"; t["--destructive-text"] = SCALES.dark.red["600"]; }
      apply(p, t);
      p.querySelectorAll(".ui-btn.is-destructive").forEach((b) => (b.style.color = p.dataset.mode === "dark" ? "#09090b" : "#fafafa"));
    });
    const code = codeSide.querySelector("#f2c-src code"), out = codeSide.querySelector(".ds-f2c-out");
    const show = (name) => {
      code.innerHTML = hl(FILES[name].src);
      out.dataset.part = FILES[name].part;
      codeSide.querySelectorAll('[role="tab"]').forEach((b) => b.setAttribute("aria-selected", String(b.dataset.file === name)));
    };
    codeSide.querySelector(".ds-f2c-tabs").addEventListener("click", (e) => { const b = e.target.closest("[data-file]"); if (b) show(b.dataset.file); });
    codeSide.querySelector(".ds-f2c-tabs").addEventListener("keydown", (e) => {
      const i = names.indexOf(document.activeElement.dataset.file); if (i < 0) return;
      const j = e.key === "ArrowRight" ? (i + 1) % names.length : e.key === "ArrowLeft" ? (i + names.length - 1) % names.length : -1;
      if (j >= 0) { e.preventDefault(); show(names[j]); codeSide.querySelector(`#f2c-tab-${j}`).focus(); }
    });
    show(names[0]);
    const stage = document.getElementById("f2c-stage");
    document.querySelectorAll('input[name="f2c"]').forEach((r) => r.addEventListener("change", () => { stage.dataset.show = r.value; }));
  }

  /* ---------- overview: an exploded build. A base plate (the shared package); three products lifted off it, each
     sitting on a different part of it and overhanging its edge a little, because each adds parts of its own; two
     clients lifted off each product and users above them, always inside their product. Dashed outlines are seats,
     dashed lines drop each part back into place. ---------- */
  const layers = document.getElementById("layers");
  if (layers) {
    const C30 = 0.866, S30 = 0.5, OX = 250, OY = 326;
    const P = (x, y, z) => [OX + (x - y) * C30, OY + (x + y) * S30 - z];
    const f1 = (n) => n.toFixed(1);
    const pts = (a) => a.map(([x, y]) => `${f1(x)},${f1(y)}`).join(" ");
    const shade = (hex, t) => mix("#000000", hex, t);
    const box = (x0, y0, x1, y1, z, h, cls, col) => {
      const f = col ? `style="--t:${col};--l:${shade(col, 0.16)};--r:${shade(col, 0.32)}"` : "";
      return `<g class="ob ${cls}" ${f}>
        <polygon class="r" points="${pts([P(x1, y0, z), P(x1, y1, z), P(x1, y1, z - h), P(x1, y0, z - h)])}"/>
        <polygon class="l" points="${pts([P(x0, y1, z), P(x1, y1, z), P(x1, y1, z - h), P(x0, y1, z - h)])}"/>
        <polygon class="t" points="${pts([P(x0, y0, z), P(x1, y0, z), P(x1, y1, z), P(x0, y1, z)])}"/></g>`;
    };
    const quad = (x0, y0, x1, y1, z) => pts([P(x0, y0, z), P(x1, y0, z), P(x1, y1, z), P(x0, y1, z)]);
    const RX = 1.2247, RY = 0.7071;
    const stud = (x, y, z, r, h, cls = "", style = "") => {
      const [X, Y] = P(x, y, z), Yt = Y - h;
      return `<g class="os ${cls}" ${style}><path class="s" d="M${f1(X - r * RX)} ${f1(Y)} A${f1(r * RX)} ${f1(r * RY)} 0 0 0 ${f1(X + r * RX)} ${f1(Y)} L${f1(X + r * RX)} ${f1(Yt)} L${f1(X - r * RX)} ${f1(Yt)} Z"/><ellipse class="c" cx="${f1(X)}" cy="${f1(Yt)}" rx="${f1(r * RX)}" ry="${f1(r * RY)}"/></g>`;
    };
    const studs = (x0, y0, x1, y1, z, step, r, h, cls) => {
      const out = [];
      const nx = Math.round((x1 - x0) / step), ny = Math.round((y1 - y0) / step);
      const sx = (x1 - x0) / nx, sy = (y1 - y0) / ny;
      for (let i = 0; i < nx; i++) for (let j = 0; j < ny; j++) out.push([x0 + sx * (i + 0.5), y0 + sy * (j + 0.5)]);
      out.sort((a, b) => a[0] + a[1] - (b[0] + b[1]));
      return out.map(([x, y]) => stud(x, y, z, r, h, cls)).join("");
    };
    const seat = (x0, y0, x1, y1, z, on) => `<polygon class="seat${on ? " is-on" : ""}" points="${quad(x0, y0, x1, y1, z)}"/>`;
    const line = (a, b, cls, style = "") => `<line class="${cls}" ${style ? `style="${style}"` : ""} x1="${f1(a[0])}" y1="${f1(a[1])}" x2="${f1(b[0])}" y2="${f1(b[1])}"/>`;
    const guides = (x0, y0, x1, y1, zFrom, zTo, on, col) => [[x1, y0], [x1, y1], [x0, y1]].map(([x, y]) => line(P(x, y, zFrom), P(x, y, zTo), `guide${on ? " is-on" : ""}`, on && col ? `stroke:${col}` : "")).join("");

    // users as chess pieces: each keeps the client's brand and changes one thing of its own
    const ell = (X, Y, r, cls) => `<ellipse class="${cls}" cx="${f1(X)}" cy="${f1(Y)}" rx="${f1(r * RX)}" ry="${f1(r * RY)}"/>`;
    const frustum = (X, Yb, r1, Yt, r2, cls) => `<path class="${cls}" d="M${f1(X - r1 * RX)} ${f1(Yb)} A${f1(r1 * RX)} ${f1(r1 * RY)} 0 0 0 ${f1(X + r1 * RX)} ${f1(Yb)} L${f1(X + r2 * RX)} ${f1(Yt)} A${f1(r2 * RX)} ${f1(r2 * RY)} 0 0 1 ${f1(X - r2 * RX)} ${f1(Yt)} Z"/>${ell(X, Yt, r2, cls)}`;
    const piece = (kind, x, y, z, tone) => {
      const [X, Y] = P(x, y, z);
      let s = `<g class="pc ${tone}" transform="translate(${f1(X)} ${f1(Y)}) scale(1.3) translate(${f1(-X)} ${f1(-Y)})">` + frustum(X, Y, 7.2, Y - 3.2, 7.2, "pc-b") + frustum(X, Y - 3.2, 6.2, Y - 5, 5.6, "pc-b");
      if (kind === "pawn") {
        s += frustum(X, Y - 5, 4.8, Y - 16, 2.6, "pc-b") + frustum(X, Y - 16, 4.2, Y - 17.8, 4.2, "pc-a") + `<circle class="pc-a" cx="${f1(X)}" cy="${f1(Y - 22.6)}" r="5.4"/>`;
      } else if (kind === "rook") {
        s += frustum(X, Y - 5, 5.2, Y - 19, 4.4, "pc-b") + frustum(X, Y - 19, 6.4, Y - 25, 6.4, "pc-a") + ell(X, Y - 25, 4.2, "pc-in");
        [-0.55, 0.55].forEach((t) => { s += `<rect class="pc-notch" x="${f1(X + t * 6.4 * RX - 1.4)}" y="${f1(Y - 25 + Math.sqrt(1 - t * t) * 6.4 * RY - 0.5)}" width="2.8" height="3.4"/>`; });
      } else {
        s += frustum(X, Y - 5, 4.6, Y - 17, 2.2, "pc-b") + frustum(X, Y - 17, 3.8, Y - 18.6, 3.8, "pc-a") + `<ellipse class="pc-a" cx="${f1(X)}" cy="${f1(Y - 25.4)}" rx="5" ry="7.4"/>`;
        s += `<line class="pc-slit" x1="${f1(X - 1)}" y1="${f1(Y - 28.6)}" x2="${f1(X + 3.6)}" y2="${f1(Y - 24.2)}"/><circle class="pc-a" cx="${f1(X)}" cy="${f1(Y - 34.4)}" r="1.9"/>`;
      }
      return s + `</g>`;
    };

    // plan, on one stud grid (U = one stud): a 13 × 5 base plate; three 3 × 3 products, each on a different part of
    // it and overhanging a different edge by exactly one stud; clients are 1 × 3 bricks on a product's outer columns
    const U = 30;
    const BASE = [0, 0, 13 * U, 5 * U];
    const PRODS = [
      { at: [-1, 2] },  // the left corner, one stud past the left end
      { at: [6, 3] },   // the middle, one stud past the front edge
      { at: [11, 1] },  // the right, one stud past the right end
    ].map((p) => ({ ...p, r: [p.at[0] * U, p.at[1] * U, (p.at[0] + 3) * U, (p.at[1] + 3) * U] }));
    const CLIENTS = [
      { id: "courier", name: "Courier", colour: "#f2c94c", product: 0, col: 0, user: "pawn" },
      { id: "grocer", name: "Grocer", colour: "#3a9a4a", product: 0, col: 2 },
      { id: "bank", name: "Bank", colour: "#3651b0", product: 1, col: 0, user: "rook" },
      { id: "florist", name: "Florist", colour: "#e85d9a", product: 1, col: 2 },
      { id: "bakery", name: "Bakery", colour: "#d06a33", product: 2, col: 0 },
      { id: "studio", name: "Studio", colour: "#8a68f5", product: 2, col: 2, user: "bishop" },
    ];
    const CX = U / 2, CY = 1.5 * U;
    const Z = { base: 0, product: 105, client: 180, user: 292 }; // product and client gaps of 105 and 75 put each level's studs half a stud off the ones below; users float high enough to clear the brick behind
    const T = { base: 12, product: 10, client: 18 };
    const cliC = (k) => { const r = PRODS[k.product].r; return [r[0] + (k.col + 0.5) * U, r[1] + 1.5 * U]; };
    const USERS = [-U, 0, U]; // one user over each stud of the brick, back to front
    const TONE = { pawn: "is-brand", rook: "is-dark", bishop: "is-own" };
    const order = [0, 1, 2].sort((a, b) => PRODS[a].r[0] + PRODS[a].r[1] - (PRODS[b].r[0] + PRODS[b].r[1]));
    // the part of a product past the base's edge: what it adds on its own
    const own = ([x0, y0, x1, y1]) => {
      const [bx0, by0, bx1, by1] = BASE, out = [];
      if (x0 < bx0) out.push([x0, y0, bx0, y1]); if (x1 > bx1) out.push([bx1, y0, x1, y1]);
      const ax0 = Math.max(x0, bx0), ax1 = Math.min(x1, bx1);
      if (y0 < by0) out.push([ax0, y0, ax1, by0]); if (y1 > by1) out.push([ax0, by1, ax1, y1]);
      return out;
    };
    const ownSvg = (rs, z) => rs.map((r) => `<polygon class="o-own-t" points="${quad(...r, z)}"/><polygon class="o-own" points="${quad(...r, z)}"/>`).join("");
    const draw = (c) => {
      const act = CLIENTS.find((k) => k.id === c.id);
      const aP = act ? act.product : 0;
      let g = `<svg viewBox="0 0 954 626" role="img" aria-label="An exploded build. A long base plate, the shared package; three products lifted above it, each on a different part of the plate and overhanging its edge a little; two clients above each product and users above each client, inside their product. Each level overrides only what it needs.">`;
      g += `<defs><pattern id="ov-hatch" width="5" height="5" patternUnits="userSpaceOnUse" patternTransform="rotate(-30)"><line class="hx-l" x1="0" y1="0" x2="0" y2="5"/></pattern>
        <filter id="ov-blur" x="-10%" y="-10%" width="120%" height="140%"><feGaussianBlur stdDeviation="8"/></filter></defs>`;
      const [bx0, by0, bx1, by1] = BASE;
      g += `<polygon class="o-shadow" filter="url(#ov-blur)" points="${pts([P(bx0, by0, -T.base), P(bx1, by0, -T.base), P(bx1, by1, -T.base), P(bx0, by1, -T.base)].map(([x, y]) => [x + 4, y + 12]))}"/>`;
      // 1 · the base plate and its studs; the products' seats, which run past its edges
      g += box(bx0, by0, bx1, by1, Z.base, T.base, `o-base${act ? "" : " is-on"}`);
      g += studs(bx0, by0, bx1, by1, Z.base, U, 5.6, 3, "on-base");
      order.forEach((p) => { g += seat(...PRODS[p].r, Z.base, p === aP); });
      // back to front, one product at a time
      order.forEach((p) => {
        const on = p === aP, R = PRODS[p].r;
        g += guides(...R, Z.product - T.product, Z.base, on);
        g += box(...R, Z.product, T.product, `o-prod${on ? " is-on" : ""}`);
        const ownR = own(R);
        g += ownSvg(ownR, Z.product);
        const ks = CLIENTS.filter((k) => k.product === p).sort((a, b) => cliC(a)[0] + cliC(a)[1] - (cliC(b)[0] + cliC(b)[1]));
        ks.forEach((k) => { const [cx, cy] = cliC(k); g += seat(cx - CX, cy - CY, cx + CX, cy + CY, Z.product, k === act); });
        g += studs(...R, Z.product, U, 5, 2.6, "on-prod");
        ks.forEach((k) => {
          const [cx, cy] = cliC(k), kon = k === act;
          g += guides(cx - CX, cy - CY, cx + CX, cy + CY, Z.client - T.client, Z.product, kon, k.colour);
          g += box(cx - CX, cy - CY, cx + CX, cy + CY, Z.client, T.client, `o-cli${kon ? " is-on" : ""}`, k.colour);
          USERS.forEach((dy) => { g += stud(cx, cy + dy, Z.client, 5, 3, "on-cli", `style="--t:${k.colour};--l:${shade(k.colour, 0.22)}"`); });
          // users: one stud each; on three clients, one user is drawn as a piece, each a different one
          const mine = "#1c9a92"; // the bishop's user picked a colour of their own
          USERS.forEach((dy, i) => {
            const isPiece = k.user && i === 1, gs = `guide${kon ? " is-on" : isPiece ? "" : " is-user"}`;
            g += line(P(cx, cy + dy, Z.client + 3), P(cx, cy + dy, isPiece ? Z.user : Z.user - 4), gs, kon ? `stroke:${k.colour}` : "");
            g += isPiece ? `<g style="--brand:${k.colour};--own:${mine}">${piece(k.user, cx, cy + dy, Z.user, TONE[k.user])}</g>` : stud(cx, cy + dy, Z.user - 4, 5, 4, `o-user${kon ? " is-on" : ""}`);
          });
        });
      });
      if (act) { const [x, y] = cliC(act); const [X, Y] = P(x - CX, y + CY, Z.client - T.client / 2); g += line([X - 4, Y], [X - 24, Y], "o-leader") + `<circle class="o-tick" cx="${f1(X - 4)}" cy="${f1(Y)}" r="2"/><text class="o-callname" x="${f1(X - 30)}" y="${f1(Y + 5)}" text-anchor="end">${act.name}</text>`; }
      // callouts, numbered, to a legend on the right; anchored on the right-hand product
      const LX = 712, kR = cliC(CLIENTS[5]), pr = PRODS[2].r;
      const rows = [
        [4, "Users", "their own look", (() => { const [X, Y] = P(kR[0], kR[1] - U, Z.user - 4); return [X + 8, Y - 4]; })()],
        [3, "Clients", "colour, font, button shape", P(kR[0] + CX, kR[1] - CY, Z.client - T.client / 2)],
        [2, "Products", "its own parts, hatched", P(pr[2], pr[1], Z.product - T.product / 2)],
        [1, "Shared package", "sets every token", P(bx1, by1 - U / 2, -T.base / 2)],
      ];
      rows.forEach(([n, t, s2, [ax, ay]]) => {
        g += line([ax + 4, ay], [LX - 22, ay], "o-leader") + `<circle class="o-tick" cx="${f1(ax + 4)}" cy="${f1(ay)}" r="2.2"/>`;
        g += `<circle class="o-num" cx="${LX - 10}" cy="${f1(ay)}" r="10"/><text class="o-numt" x="${LX - 10}" y="${f1(ay + 4)}" text-anchor="middle">${n}</text>`;
        g += `<text class="o-ln" x="${LX + 8}" y="${f1(ay - 2)}">${t}</text><text class="o-ls" x="${LX + 8}" y="${f1(ay + 15)}">${s2}</text>`;
      });
      g += `</svg>`;
      layers.innerHTML = g;
    };
    listeners.push(draw);
  }

  /* ---------- 02.1: a wall of the scales ---------- */
  const wall = document.getElementById("wall");
  if (wall) {
    const L = SCALES.light;
    const cell = (h, st) => {
      const c = L[h][st];
      if (st === "600") return `<div class="ds-wall-c" style="background:${c};color:#fff"><small>on white</small><span>${ratio(c, "#ffffff").toFixed(1)}</span></div>`;
      if (st === "700") return `<div class="ds-wall-c" style="background:${c};color:${L[h]["50"]}"><small>on its 50</small><span>${ratio(c, L[h]["50"]).toFixed(1)}</span></div>`;
      return `<div class="ds-wall-c" style="background:${c}"><span class="sr-only">${h} ${st}</span></div>`;
    };
    wall.innerHTML = `<div class="ds-wall-grid" role="table" aria-label="Six roles, five steps, each step with one job">
      <div role="row" class="ds-wall-row"><div class="ds-wall-h" role="columnheader"><span class="sr-only">Role</span></div>${STEPS.map(([st, job]) => `<div class="ds-wall-h" role="columnheader"><b>${job}</b>${st}</div>`).join("")}</div>
      ${HUES.map(([h, name, role]) => `<div role="row" class="ds-wall-row"><div class="ds-wall-role" role="rowheader"><b>${role}</b><span>${name.toLowerCase()}</span></div>${STEPS.map(([st]) => cell(h, st)).join("")}</div>`).join("")}
    </div>`;
  }

  /* ---------- 02.2: lightness chart (on the dark sheet) ---------- */
  const chart = document.getElementById("light-chart");
  if (chart) {
    const W = 760, left = 150, right = 20, rowH = 42, top = 14, x0 = 0.4, x1 = 1.0;
    const rows = [["50", "Surface"], ["200", "Border"], ["500", "Charts, icons"], ["600", "Text on white"], ["700", "Text on a tint"]];
    const H = top + rows.length * rowH + 34;
    const X = (l) => left + ((l - x0) / (x1 - x0)) * (W - left - right);
    const order = ["brand", "blue", "green", "red", "purple", "amber"];
    let g = `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Lightness of each step on six hues. Text on white sits between 0.50 and 0.54; text on a tint between 0.44 and 0.48.">`;
    rows.forEach(([st, job], i) => {
      const y = top + i * rowH + rowH / 2;
      const ls = Object.values(REAL_L[st]);
      const mn = Math.min(...ls), mx = Math.max(...ls);
      g += `<text class="row-l" x="0" y="${y + 4}">${job}</text><text class="lbl" x="${left - 12}" y="${y + 4}" text-anchor="end">${st}</text>`;
      g += `<line class="ax" x1="${left}" x2="${W - right}" y1="${y}" y2="${y}"/>`;
      g += `<rect class="band" x="${X(mn) - 11}" y="${y - 16}" width="${X(mx) - X(mn) + 22}" height="32" rx="16"/>`;
      order.filter((h) => REAL_L[st][h] != null).forEach((h, j, arr) => {
        const dy = (j - (arr.length - 1) / 2) * 4.4;
        g += `<circle cx="${X(REAL_L[st][h]).toFixed(1)}" cy="${(y + dy).toFixed(1)}" r="6.5" fill="${SCALES.light[h][st]}"><title>${h} ${st}: L ${REAL_L[st][h]}</title></circle>`;
      });
    });
    const yA = top + rows.length * rowH + 8;
    [0.4, 0.5, 0.6, 0.7, 0.8, 0.9, 1.0].forEach((v) => { g += `<g class="tick"><line class="ax" x1="${X(v)}" x2="${X(v)}" y1="${yA - 4}" y2="${yA + 2}"/><text x="${X(v)}" y="${yA + 18}" text-anchor="middle">${v.toFixed(1)}</text></g>`; });
    g += `<text class="lbl" x="0" y="${yA + 18}">OKLCH lightness</text></svg>`;
    chart.innerHTML = g;
  }

  /* ---------- 02.3: one specimen, light and dark, split by a slider ---------- */
  const split = document.getElementById("split");
  if (split) {
    const layer = (mode) => {
      const S = SCALES[mode], bg = NEUTRAL[mode].card;
      return `<div class="ds-split-layer is-${mode}" ${mode === "dark" ? 'aria-hidden="true"' : ""}><div class="ds-split-h"><span>${mode === "light" ? "Light" : "Dark"}</span><span>border · text · text on a tint</span></div>
        ${HUES.map(([h, name]) => `<div class="ds-split-row"><span>${name}</span>
          <i class="is-border" style="--c:${S[h]["200"]}"><span class="sr-only">border</span></i>
          <i style="color:${S[h]["600"]}">Aa <small>${ratio(S[h]["600"], bg).toFixed(1)}</small></i>
          <i style="background:${S[h]["50"]};color:${S[h]["700"]}">Aa <small>${ratio(S[h]["700"], S[h]["50"]).toFixed(1)}</small></i></div>`).join("")}</div>`;
    };
    // the divider is the control: drag it (or anywhere on the specimen), or focus it and use the arrow keys
    split.innerHTML = `<div class="ds-split-stage" id="split-stage">${layer("light")}${layer("dark")}
      <span class="ds-split-handle"></span><span class="ds-split-grip" role="slider" tabindex="0" aria-label="Move between the light and dark versions of the same specimen" aria-valuemin="0" aria-valuemax="100" aria-valuenow="50" aria-valuetext="Half light, half dark"><b aria-hidden="true">‹</b>Light · Dark<b aria-hidden="true">›</b></span></div>`;
    const stage = split.querySelector("#split-stage"), grip = split.querySelector(".ds-split-grip");
    const set = (v) => {
      v = Math.max(0, Math.min(100, v));
      stage.style.setProperty("--split", `${v}%`);
      grip.setAttribute("aria-valuenow", String(Math.round(v)));
      grip.setAttribute("aria-valuetext", v < 5 ? "All dark" : v > 95 ? "All light" : `${Math.round(v)}% light`);
    };
    const fromX = (x) => { const r = stage.getBoundingClientRect(); set(((x - r.left) / r.width) * 100); };
    let dragging = false;
    stage.addEventListener("pointerdown", (e) => { dragging = true; stage.setPointerCapture(e.pointerId); stage.classList.add("is-dragging"); fromX(e.clientX); });
    stage.addEventListener("pointermove", (e) => { if (dragging) fromX(e.clientX); });
    const stop = () => { dragging = false; stage.classList.remove("is-dragging"); };
    stage.addEventListener("pointerup", stop); stage.addEventListener("pointercancel", stop);
    grip.addEventListener("keydown", (e) => {
      const now = Number(grip.getAttribute("aria-valuenow")), step = e.shiftKey ? 20 : 5;
      const next = { ArrowLeft: now - step, ArrowDown: now - step, ArrowRight: now + step, ArrowUp: now + step, Home: 0, End: 100 }[e.key];
      if (next != null) { e.preventDefault(); set(next); }
    });
  }

  /* ---------- 02.4: a customer's colour, passed through or derived ---------- */
  const cc = document.getElementById("cc");
  if (cc) {
    const COLOURS = { yellow: ["Pale yellow", "#fff29a"], navy: ["Navy", "#1d2b5c"] };
    cc.innerHTML = `
      <div class="cc-top">
        <div class="ds-seg" role="radiogroup" aria-label="Customer colour">
          <label><input type="radio" name="cc-colour" id="cc-yellow" value="yellow" checked><span class="tp-swatch" style="background:#fff29a"></span>Pale yellow</label>
          <label><input type="radio" name="cc-colour" id="cc-navy" value="navy"><span class="tp-swatch" style="background:#1d2b5c"></span>Navy</label>
        </div>
        <div class="ds-seg" role="radiogroup" aria-label="Rule">
          <label><input type="radio" name="cc-rule" id="cc-pass" value="passed">Passed through</label>
          <label><input type="radio" name="cc-rule" id="cc-derived" value="derived" checked>Derived</label>
        </div>
      </div>
      <div class="cc-modes" id="cc-modes"></div>`;
    const out = cc.querySelector("#cc-modes");
    const render = () => {
      const [, hex] = COLOURS[cc.querySelector('input[name="cc-colour"]:checked').value];
      const rule = cc.querySelector('input[name="cc-rule"]:checked').value;
      out.innerHTML = ["light", "dark"].map((mode) => `<div class="cc-pane ui" data-mode="${mode}">
          <span class="ds-label">${mode === "light" ? "Light" : "Dark"}</span>
          <div class="cc-line"><span class="ui-btn is-primary" style="display:inline-block">New run</span><span data-r="btn"></span></div>
          <div class="cc-line"><span class="ui-brandtext">Text in the brand colour</span><span data-r="link"></span></div>
          <div class="cc-line"><span class="ui-badge r-primary">Today</span><span data-r="tab"></span></div>
        </div>`).join("");
      out.querySelectorAll(".cc-pane").forEach((p) => {
        const t = theme(hex, p.dataset.mode, rule);
        apply(p, t);
        p.style.colorScheme = p.dataset.mode;
        const set = (k, r) => { p.querySelector(`[data-r="${k}"]`).innerHTML = chip(r); };
        set("btn", ratio(t["--primary-fg"], t["--primary"]));
        set("link", ratio(t["--primary-text"], t["--card"]));
        set("tab", ratio(t["--primary-container-fg"], t["--primary-container"]));
      });
    };
    cc.addEventListener("change", render);
    render();
  }

  /* ---------- contents: mark the card in view ---------- */
  const toc = document.querySelector(".cf-toc");
  if (toc) {
    const links = [...toc.querySelectorAll("a[href^='#']")];
    const ids = links.map((a) => a.getAttribute("href").slice(1)).filter((id) => id !== "top");
    let raf = 0;
    const update = () => {
      raf = 0;
      const line = innerHeight * 0.4;
      let cur = null;
      for (const id of ids) { const el = document.getElementById(id); if (el && el.getBoundingClientRect().top <= line) cur = id; }
      links.forEach((a) => a.removeAttribute("aria-current"));
      const at = links.find((a) => a.getAttribute("href") === `#${cur ?? "top"}`);
      if (at) at.setAttribute("aria-current", "step");
      toc.querySelectorAll(".cf-toc-part").forEach((li) => li.dataset.active = String(!!cur && !!li.querySelector(`a[href="#${cur}"]`)));
    };
    addEventListener("scroll", () => { if (!raf) raf = requestAnimationFrame(update); }, { passive: true });
    addEventListener("resize", () => { if (!raf) raf = requestAnimationFrame(update); });
    update();
  }

  /* ---------- review: theme switch ---------- */
  const bar = document.querySelector(".proto-bar");
  if (bar) {
    const set = (v) => {
      if (v === "system") document.documentElement.removeAttribute("data-theme"); else document.documentElement.setAttribute("data-theme", v);
      bar.querySelectorAll("button").forEach((b) => b.setAttribute("aria-pressed", String(b.dataset.themeSet === v)));
    };
    bar.addEventListener("click", (e) => { const b = e.target.closest("button"); if (b) set(b.dataset.themeSet); });
  }

  setCustomer("courier");
})();
